import{_ as t,o,c as d,a3 as c}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"CMake API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"CMake API | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/cmake-api"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/cmake-api"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/cmake-api"}]]},"headers":[],"relativePath":"xclang/reference/cmake-api.md","filePath":"en/xclang/reference/cmake-api.md","lastUpdated":1791579933000}'),a={name:"xclang/reference/cmake-api.md"};function i(r,e,n,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="cmake-api" tabindex="-1">CMake API <a class="header-anchor" href="#cmake-api" aria-label="Permalink to &quot;CMake API&quot;">​</a></h1><p>Everything the CMake package of xclang defines. How to use it is in <a href="./../integrations/cmake">CMake</a>; this page is the list.</p><p>The package is <code>lib/cmake/xclang</code> of every toolchain directory, and so of the conda package, and <code>packages/cmake/</code> of the repository at every tag. It needs CMake 3.28 or later. For C++20 modules, it needs the Ninja or Ninja Multi-Config generator, with Ninja 1.11 or later.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>file</th><th>what it is</th></tr></thead><tbody><tr><td><code>xclang-config.cmake</code></td><td><code>find_package(xclang)</code>: <code>xclang::std</code>, <code>xclang_add_std()</code>, <code>xclang_debug_symbols()</code>, <code>XCLANG_ROOT</code>, the ThinLTO cache</td></tr><tr><td><code>xclang-config-version.cmake</code></td><td>the release, for <code>find_package(xclang 23.1)</code> (toolchain archives only)</td></tr><tr><td><code>toolchain.cmake</code></td><td>the toolchain directory as the toolchain of a build, for the host or <code>XCLANG_TARGET</code></td></tr><tr><td><code>runtimes.cmake</code></td><td>included by <code>toolchain.cmake</code>: the runtimes built from source, and the build&#39;s sanitizers (from the release after 23.1.2.10)</td></tr><tr><td><code>runtimes-cxx.cmake</code>, <code>runtimes-compiler-rt.cmake</code></td><td>the CMake caches of xclang&#39;s own builds of libc++ and compiler-rt, which <code>runtimes.cmake</code> builds with</td></tr><tr><td><code>xclang.cmake</code></td><td>in <code>packages/cmake/</code> only: included before <code>project()</code> from a FetchContent checkout, it downloads the toolchain</td></tr></tbody></table><h2 id="find-package-xclang" tabindex="-1"><code>find_package(xclang)</code> <a class="header-anchor" href="#find-package-xclang" aria-label="Permalink to &quot;`find_package(xclang)`&quot;">​</a></h2><p>It comes after <code>project()</code> or <code>enable_language(CXX)</code>, whose C++ compiler must be xclang&#39;s <code>clang++</code>. It finds the package through <code>PATH</code> (<code>$XCLANG/bin</code> gives <code>$XCLANG/lib/cmake/xclang</code>), <code>xclang_ROOT</code>, or <code>CMAKE_PREFIX_PATH</code>.</p><table tabindex="0"><thead><tr><th>name</th><th>kind</th><th></th></tr></thead><tbody><tr><td><code>xclang::std</code></td><td>CMake target</td><td>a static library of the <code>std</code> and <code>std.compat</code> modules of libc++ (of Microsoft&#39;s STL for an MSVC target with <code>-stdlib=platform</code>), for the build&#39;s target; built only when something links it (<a href="./../integrations/cmake#use-c-20-modules-and-import-std">language options</a>)</td></tr><tr><td><code>xclang_add_std(&lt;name&gt;)</code></td><td>function</td><td>another such library; its <code>PUBLIC</code> options reach its importers</td></tr><tr><td><code>xclang_debug_symbols(&lt;program&gt; [GSYM_ARGS &lt;option&gt;...])</code></td><td>function</td><td>after each link of the CMake target <code>&lt;program&gt;</code>: <code>&lt;program&gt;.gsym</code> next to it, by llvm-gsymutil with one thread (the same file each run; <code>GSYM_ARGS</code> come after <code>--num-threads=1</code>), with its output in <code>&lt;program&gt;.gsym.log</code>; for a macOS target, <code>&lt;program&gt;.dSYM</code> first (<a href="./../features/debugging#usage">debugging</a>); nothing for an MSVC target, whose link writes a PDB</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>variable</td><td>the toolchain directory</td></tr><tr><td><code>XCLANG_THINLTO_CACHE</code></td><td>cache variable</td><td>an absolute directory for the ThinLTO cache of the linker; its first value comes from the environment variable of the same name (<a href="./../features/thinlto-cache#usage">the ThinLTO cache</a>)</td></tr></tbody></table><p><code>xclang::std</code> asks its importers for C++23, or for the <code>CMAKE_CXX_STANDARD</code> it was built with if that is 20 or later. With <code>XCLANG_RUNTIMES=source</code>, it is built from the variant&#39;s modules and headers; that option needs the toolchain file, and <code>find_package(xclang)</code> fails without it.</p><h2 id="toolchain-cmake" tabindex="-1"><code>toolchain.cmake</code> <a class="header-anchor" href="#toolchain-cmake" aria-label="Permalink to &quot;`toolchain.cmake`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake -G Ninja -B build --toolchain $XCLANG/lib/cmake/xclang/toolchain.cmake [-DXCLANG_TARGET=&lt;target&gt;]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_TARGET</code></td><td><code>x86_64-unknown-linux-gnu</code>, <code>aarch64-unknown-linux-gnu</code>, <code>x86_64-unknown-linux-musl</code>, <code>aarch64-unknown-linux-musl</code>, <code>x86_64-w64-mingw32</code>, <code>aarch64-w64-mingw32</code>, <code>aarch64-apple-darwin</code>, <code>x86_64-apple-darwin</code>, <code>x86_64-pc-windows-msvc</code> or <code>aarch64-pc-windows-msvc</code>; the host&#39;s by default. The MSVC targets, and the macOS targets on Linux and Windows hosts, build with the SDK that the toolchain&#39;s <code>xclang</code> fetched. The musl targets, from 23.1.2.10 on, are no cross build on a Linux host of their architecture, which runs their static programs (<code>try_run</code>, tests)</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>the toolchain directory, when the file is used from outside one</td></tr><tr><td><code>XCLANG_MSVC_STL</code></td><td><code>ON</code>: an MSVC target&#39;s C++ library is Microsoft&#39;s STL, not libc++ (<code>-stdlib=platform</code> in <code>CMAKE_CXX_FLAGS</code>), and <code>xclang::std</code> the STL&#39;s; ignored for other targets</td></tr><tr><td><code>XCLANG_RUNTIMES</code>, <code>XCLANG_SANITIZER</code>, ...</td><td>the runtimes built from source and the build&#39;s sanitizers (<a href="#runtimes-from-source">below</a>)</td></tr></tbody></table><p>It sets the C, C++ and ASM compilers, and the binary tools, to those of the toolchain directory: <code>llvm-ar</code>, <code>llvm-ranlib</code>, <code>llvm-nm</code>, <code>llvm-objcopy</code>, <code>llvm-objdump</code>, <code>llvm-readelf</code>, <code>llvm-strip</code>, <code>llvm-addr2line</code>, <code>llvm-dlltool</code>; for Windows targets <code>llvm-windres</code> as the RC compiler; for macOS targets the Objective-C compilers (clang and clang++), <code>llvm-libtool-darwin</code>, <code>llvm-lipo</code> and <code>llvm-install-name-tool</code> (Apple&#39;s <code>libtool</code> cannot read the bitcode of a newer LLVM).</p><p>For a Linux or Windows target other than the host, it also sets <code>CMAKE_SYSTEM_NAME</code>, <code>CMAKE_SYSTEM_PROCESSOR</code>, <code>CMAKE_&lt;LANG&gt;_COMPILER_TARGET</code>, <code>CMAKE_SYSROOT</code> (the sysroot of the target) and <code>CMAKE_FIND_ROOT_PATH_MODE_{LIBRARY,INCLUDE,PACKAGE}</code> to <code>ONLY</code>, so libraries, headers and packages are looked for in the sysroot alone, and programs on the host. The other macOS architecture is <code>CMAKE_OSX_ARCHITECTURES</code>, which CMake does not treat as cross-compiling. The sysroot, C++ library, runtimes and linker come from the config file of the target, not from this file.</p><p>For an MSVC target on a Linux or macOS host, it stops unless the toolchain&#39;s <code>sdk/windows</code> has the SDK for the target; on a Windows host without one, clang finds Visual Studio. It sets <code>llvm-rc</code> as the RC compiler, which CMake runs on the output of the target&#39;s clang. <code>CMAKE_MSVC_RUNTIME_LIBRARY</code> is <code>MultiThreaded</code> unless set, and a link with <code>MultiThreadedDebug</code> or <code>MultiThreadedDebugDLL</code> gets <code>/nodefaultlib:ucrt.lib</code>. The SDK is <code>CMAKE_FIND_ROOT_PATH</code>, except on a Windows host for its own architecture, which is no cross build to CMake, and on a Windows host without one.</p><p>For a macOS target on a Linux or Windows host, <code>CMAKE_OSX_SYSROOT</code> is the one given, else <code>SDKROOT</code>, else the toolchain&#39;s <code>sdk/macos</code>, and it stops if that has no SDK. It sets <code>CMAKE_SYSTEM_NAME</code> to <code>Darwin</code>, <code>CMAKE_SYSTEM_PROCESSOR</code> and <code>CMAKE_OSX_ARCHITECTURES</code> to <code>arm64</code> or <code>x86_64</code>, <code>CMAKE_&lt;LANG&gt;_COMPILER_TARGET</code> (C, C++, ASM, Objective-C), and the SDK as <code>CMAKE_FIND_ROOT_PATH</code>, with the modes above.</p><h3 id="runtimes-from-source" tabindex="-1">Runtimes from Source <a class="header-anchor" href="#runtimes-from-source" aria-label="Permalink to &quot;Runtimes from Source&quot;">​</a></h3><p>In no release yet (<a href="./../design/roadmap#libc-on-demand">Unreleased</a>). <code>runtimes.cmake</code>, which the toolchain file includes, reads these variables (<a href="./../features/runtimes-from-source">runtimes from source</a>):</p><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_RUNTIMES</code></td><td><code>prebuilt</code>, the default: the toolchain&#39;s runtimes. <code>source</code>: libc++ (with libc++abi), libc++experimental and libunwind built from the toolchain&#39;s <code>libc++/src</code> for the target, with the options below, at the first configure that asks for the variant; every compile and link of the build is against them in place of the prebuilt ones, <code>try_compile</code>&#39;s too. Not for the MSVC targets</td></tr><tr><td><code>XCLANG_SANITIZER</code></td><td>a list of <code>address</code>, <code>memory</code>, <code>thread</code>, <code>undefined</code>, <code>leak</code>: <code>-fsanitize=</code> on every compile and link of the build, and runtimes that suit it. With the prebuilt runtimes, <code>address</code> adds the ASan libc++ where the target has one, and <code>memory</code> stops the configure; with <code>source</code>, the runtimes are built with the sanitizers (<code>LLVM_USE_SANITIZER</code>), and <code>memory</code> builds compiler-rt&#39;s MemorySanitizer runtime too, linked into executables</td></tr><tr><td><code>XCLANG_LIBCXX_HARDENING</code></td><td><code>none</code>, <code>fast</code>, <code>extensive</code> or <code>debug</code>: libc++&#39;s hardening mode (<code>LIBCXX_HARDENING_MODE</code>), of the library and the default of its headers</td></tr><tr><td><code>XCLANG_LIBCXX_ABI_VERSION</code></td><td><code>1</code> or <code>2</code> (<code>LIBCXX_ABI_VERSION</code>)</td></tr><tr><td><code>XCLANG_LIBCXX_ABI_NAMESPACE</code></td><td>libc++&#39;s inline namespace, <code>__&lt;name&gt;</code> (<code>LIBCXX_ABI_NAMESPACE</code>)</td></tr><tr><td><code>XCLANG_LIBCXX_ABI_DEFINES</code></td><td>a list of libc++&#39;s ABI macros, such as <code>_LIBCPP_ABI_BOUNDED_ITERATORS</code> (<code>LIBCXX_ABI_DEFINES</code>)</td></tr><tr><td><code>XCLANG_RUNTIMES_EXCEPTIONS</code></td><td><code>OFF</code>: libc++ and libc++abi without exceptions</td></tr><tr><td><code>XCLANG_RUNTIMES_RTTI</code></td><td><code>OFF</code>: libc++ without RTTI; needs <code>XCLANG_RUNTIMES_EXCEPTIONS=OFF</code></td></tr><tr><td><code>XCLANG_RUNTIMES_FLAGS</code></td><td>more compile options of libc++ and libc++abi, such as <code>-flto=thin</code></td></tr><tr><td><code>XCLANG_RUNTIMES_CMAKE_ARGS</code></td><td>more arguments of the runtimes&#39; CMake build, LLVM&#39;s <code>runtimes/</code>, <code>-D&lt;variable&gt;=&lt;value&gt;</code> each</td></tr><tr><td><code>XCLANG_RUNTIMES_DIR</code></td><td>where the variants are built, <code>&lt;target&gt;-&lt;digest&gt;</code> each; <code>${CMAKE_BINARY_DIR}/xclang-runtimes</code> by default</td></tr></tbody></table><p>The options but <code>XCLANG_RUNTIMES</code> and <code>XCLANG_SANITIZER</code> need <code>XCLANG_RUNTIMES=source</code>. A variant&#39;s directory holds its CMake builds (<code>runtimes</code>, and with MemorySanitizer <code>compiler-rt</code>), their logs, and <code>install</code>: <code>include/c++/v1</code>, the headers, <code>__config_site</code> among them, which come before the config file&#39;s with <code>-nostdinc++</code>; <code>lib</code>, the libraries, linked with <code>-nostdlib++</code> and, but for macOS and with sanitizers, <code>--unwindlib=none</code>; <code>lib/libc++.modules.json</code> and <code>share/libc++/v1</code>, the modules of <code>xclang::std</code>. Its name is a digest of the options, the target and the toolchain, so a variant is built once per build directory, and another set of options builds another beside it. The build needs Python 3, as LLVM&#39;s does.</p><h2 id="xclang-cmake" tabindex="-1"><code>xclang.cmake</code> <a class="header-anchor" href="#xclang-cmake" aria-label="Permalink to &quot;`xclang.cmake`&quot;">​</a></h2><p>Included before <code>project()</code>, from a FetchContent checkout of the tag of a release (<a href="./../integrations/cmake#without-xclang-installed">CMake</a> has the snippet):</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">${xclang_SOURCE_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/packages/cmake/xclang.cmake)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_VERSION</code></td><td>the release to download; without it, the release tagging the checkout</td></tr><tr><td><code>XCLANG_TARGET</code></td><td>another target to build for, as for <code>toolchain.cmake</code></td></tr><tr><td><code>XCLANG_ROOT</code></td><td>an unpacked xclang to use instead of downloading one</td></tr><tr><td><code>XCLANG_CACHE_DIR</code></td><td>where toolchains are unpacked, <code>&lt;version&gt;/&lt;host&gt;</code> each (also an environment variable); by default <code>$XDG_CACHE_HOME/xclang</code> or <code>~/.cache/xclang</code>, <code>~/Library/Caches/xclang</code> on macOS, <code>%LOCALAPPDATA%\\xclang</code> on Windows</td></tr><tr><td><code>XCLANG_URL</code></td><td>where <code>SHA256SUMS</code> and the archives are downloaded from, a mirror of the release; its <code>SHA256SUMS</code> is then the one trusted</td></tr></tbody></table><p>It downloads the <code>SHA256SUMS</code> of the release and the host archive, <code>xclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code>, and checks the archive against its line. It unpacks the archive aside and moves it into the cache, so that build trees configured at once do not clash. Then it sets <code>CMAKE_TOOLCHAIN_FILE</code>. It stops if the build already has a toolchain file, such as vcpkg&#39;s; vcpkg chain-loads xclang&#39;s instead (<code>VCPKG_CHAINLOAD_TOOLCHAIN_FILE</code>).</p><h2 id="libclang-s-package" tabindex="-1">libclang&#39;s Package <a class="header-anchor" href="#libclang-s-package" aria-label="Permalink to &quot;libclang&#39;s Package&quot;">​</a></h2><p>The libclang archives carry the own CMake packages of LLVM and clang (<code>find_package(Clang)</code>). They also carry <code>lib/cmake/xclang/libclang.cmake</code>, which records the build: <code>XCLANG_LLVM_VERSION</code>, <code>XCLANG_LTO</code>, <code>XCLANG_PGO</code>, <code>XCLANG_PATCHES</code> and the like (<a href="./../features/libclang">libclang</a>).</p>',27)])])}const u=t(a,[["render",i]]);export{m as __pageData,u as default};
